    public const string Layout = """
<header class="mx-header" data-mx-header data-menu="{{param:menuStyle}}">
  <div class="mx-wrap mx-header__in">
    <a class="mx-logo" href="/" aria-label="{{site_name}}">{{logo}}</a>
    <input type="checkbox" id="mx-nav" class="mx-toggle" aria-hidden="true">
    <nav class="mx-nav" aria-label="Menü">{{#menu:primary}}<a href="{{url}}"{{target}}>{{label}}</a>{{/menu:primary}}<a class="btn mx-nav-cta" href="{{param:ctaUrl}}">{{param:ctaLabel}}</a></nav>
    <div class="mx-acts"><span class="mx-tools">{{toolbar}}</span><a class="mx-act mx-act--phone" href="tel:{{param:phone}}" aria-label="{{param:phone}}"><i class="ti ti-phone"></i><span>{{param:phone}}</span></a><a class="mx-act mx-act--wa" href="https://wa.me/{{param:whatsapp}}" target="_blank" rel="noopener" aria-label="WhatsApp"><i class="ti ti-brand-whatsapp"></i></a><a class="btn mx-cta" href="{{param:ctaUrl}}">{{param:ctaLabel}}</a></div>
    <label for="mx-nav" class="mx-burger" aria-label="Menü"><span></span><span></span><span></span></label>
  </div>
</header>
<main>{{content}}</main>
<footer class="mx-footer">
  <div class="mx-wrap mx-footer__grid">
    <div class="mx-footer__brand">{{logo}}<p>{{footer_text}}</p></div>
    <div class="mx-footer__col"><h4>{{param:contactHeading}}</h4><p class="mx-footer__contact"><a href="tel:{{param:phone}}">{{param:phone}}</a><a href="mailto:{{param:email}}">{{param:email}}</a><a href="https://wa.me/{{param:whatsapp}}" target="_blank" rel="noopener">WhatsApp</a></p></div>
    <div class="mx-footer__col"><h4>{{param:pagesHeading}}</h4><nav class="mx-footer__nav">{{#menu:primary}}<a href="{{url}}"{{target}}>{{label}}</a>{{/menu:primary}}</nav></div>
    <div class="mx-footer__col"><h4>{{param:legalHeading}}</h4><nav class="mx-footer__nav">{{#menu:secondary}}<a href="{{url}}"{{target}}>{{label}}</a>{{/menu:secondary}}</nav></div>
  </div>
  <div class="mx-wrap mx-footer__base"><span>© {{year}} {{site_name}}</span></div>
</footer>
""";

