    public const string Js = """
/* Modernisierung 2026-11: header shadow on scroll, active menu entry, reveal of blocks as they come into view. */
(function () {
  var h = document.querySelector('[data-mx-header]');
  if (h) { var on = function () { h.classList.toggle('is-scrolled', window.scrollY > 8); }; on(); window.addEventListener('scroll', on, { passive: true }); }
  var here = location.pathname.replace(/\/$/, '') || '/';
  document.querySelectorAll('.mx-nav a').forEach(function (a) { var p = (a.getAttribute('href') || '').replace(/\/$/, '') || '/'; if (p === here) a.classList.add('is-active'); });
  var t = document.getElementById('mx-nav'); if (t) document.querySelectorAll('.mx-nav a').forEach(function (a) { a.addEventListener('click', function () { t.checked = false; }); });
  if (!('IntersectionObserver' in window) || matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  var els = document.querySelectorAll('main > .block-wrap:not(:first-child) > section, .feature-card, .service-card, .column, .accordion-item, .gallery__item');
  var io = new IntersectionObserver(function (es) { es.forEach(function (e) { if (e.isIntersecting) { e.target.classList.add('is-in'); io.unobserve(e.target); } }); }, { rootMargin: '0px 0px -8% 0px' });
  els.forEach(function (el, i) { if (el.getBoundingClientRect().top < innerHeight * .9) return; el.classList.add('mx-rv'); el.style.transitionDelay = (el.matches('section') ? 0 : (i % 4) * 70) + 'ms'; io.observe(el); });
})();
""";
